static const audio_clip_t BGM_CLIP = {
    .samples = bgm_samples,
    .count = sizeof(bgm_samples) / sizeof(bgm_samples[0]),
};

static const audio_clip_t NARRATION_2 = {
    .samples = narration_2,
    .count = sizeof(narration_2) / sizeof(narration_2[0]),
};

static const audio_clip_t NARRATION_7 = {
    .samples = narration_7,
    .count = sizeof(narration_7) / sizeof(narration_7[0]),
};

static const audio_clip_t NARRATION_16 = {
    .samples = narration_16,
    .count = sizeof(narration_16) / sizeof(narration_16[0]),
};

static const audio_clip_t *const SFX_CLIPS[] = {
    &(const audio_clip_t){ .samples = sfx_0, .count = sizeof(sfx_0) / sizeof(sfx_0[0]) },
    &(const audio_clip_t){ .samples = sfx_1, .count = sizeof(sfx_1) / sizeof(sfx_1[0]) },
    &(const audio_clip_t){ .samples = sfx_2, .count = sizeof(sfx_2) / sizeof(sfx_2[0]) },
    &(const audio_clip_t){ .samples = sfx_3, .count = sizeof(sfx_3) / sizeof(sfx_3[0]) },
    &(const audio_clip_t){ .samples = sfx_4, .count = sizeof(sfx_4) / sizeof(sfx_4[0]) },
};

const audio_clip_t *poetry_audio_bgm(void)
{
    return &BGM_CLIP;
}

const audio_clip_t *poetry_audio_narration(uint16_t poem_id)
{
    switch (poem_id) {
    case 7:
        return &NARRATION_7;
    case 2:
        return &NARRATION_2;
    case 16:
        return &NARRATION_16;
    default:
        return NULL;
    }
}

const audio_clip_t *poetry_audio_sfx(uint8_t id)
{
    if (id >= POETRY_SFX_COUNT) {
        return NULL;
    }
    return SFX_CLIPS[id];
}
